[{"state": "Re: WHY was my grade changed?! —Rosa", "questions": [
{"type": "binary", "instruction": "A grade complaint means the sender objects to a mark or grade. Does this subject line contain one?", "target": true, "hard_cases": [], "notes": "sender angrily asks why the grade was changed"},
{"type": "multiclass", "instruction": "The topic is the main school matter raised. Which topic does this email subject line concern?", "candidates": [{"id": "grades", "description": "Marks or grades, e.g. 'my exam score is wrong'"}, {"id": "fees", "description": "Payments or tuition, e.g. 'I was charged twice'"}, {"id": "schedule", "description": "Class times or rooms, e.g. 'the lecture moved to 9am'"}, {"id": "none", "description": "None of the above: no listed topic applies, e.g. 'hello'"}], "target": "grades", "hard_cases": [], "notes": "subject asks about a grade change"}
]},
{"state": "ERROR enroll_fail user=yokafor course=BIO201 full", "questions": [
{"type": "binary", "instruction": "A successful enrollment means the log records the student being added to the course. Is there one here?", "target": false, "hard_cases": [], "notes": "log says enroll_fail, course full"},
{"type": "multiclass", "instruction": "The failure reason is why the system rejected the action. Which failure reason does this log line give?", "candidates": [{"id": "capacity", "description": "The course has no open seats, e.g. 'section full'"}, {"id": "prerequisite", "description": "A required earlier course is missing, e.g. 'needs CHEM101'"}, {"id": "payment_hold", "description": "Unpaid fees block the action, e.g. 'account hold'"}], "target": "capacity", "hard_cases": [], "notes": "'full' means no seats"},
{"type": "multilabel", "instruction": "A mentioned identifier is any user or course code that appears in the log. Which identifiers are mentioned?", "candidates": [{"id": "user_id", "description": "A student username, e.g. 'user=jdoe'"}, {"id": "course_code", "description": "A course code, e.g. 'MATH101'"}, {"id": "room_number", "description": "A classroom number, e.g. 'Room 214'"}], "target": ["user_id", "course_code"], "hard_cases": [], "notes": "user=yokafor and BIO201 present; no room"}
]},
{"state": "Nadia: Refund my lab fee NOW, seriously!", "questions": [
{"type": "binary", "instruction": "A refund request means the sender explicitly asks for money back. Is there one in this text message?", "target": true, "hard_cases": [], "notes": "'Refund my lab fee' is explicit"},
{"type": "multiclass", "instruction": "Tone describes the sender's emotional state. Which tone best fits this text message from Nadia?", "candidates": [{"id": "calm", "description": "Relaxed and neutral, e.g. 'no rush, thanks'"}, {"id": "angry", "description": "Upset and demanding, e.g. 'fix this immediately!'"}, {"id": "grateful", "description": "Thankful, e.g. 'thanks so much for helping'"}], "target": "angry", "hard_cases": [], "notes": "'NOW, seriously!' is demanding"}
]},
{"state": "Tomasz: Bus late again, missed the quiz!", "questions": [
{"type": "binary", "instruction": "An absence explanation means the sender gives a reason for missing class work. Does this message give one?", "target": true, "hard_cases": [], "notes": "late bus caused missing the quiz"},
{"type": "multilabel", "instruction": "A reported issue is a problem the sender says happened. Which issues does Tomasz report in this message?", "candidates": [{"id": "transport_delay", "description": "Travel was delayed, e.g. 'train was late'"}, {"id": "missed_assessment", "description": "A test or quiz was missed, e.g. 'skipped the exam'"}, {"id": "lost_login", "description": "Cannot access an account, e.g. 'forgot my password'"}, {"id": "repeated_problem", "description": "The issue has happened before, e.g. 'this keeps happening'"}], "target": ["transport_delay", "missed_assessment", "repeated_problem"], "hard_cases": [], "notes": "late bus, missed quiz, 'again'"},
{"type": "binary", "instruction": "A payment issue means the sender complains about fees or charges. Does this message raise one?", "target": false, "hard_cases": [], "notes": "no fees mentioned"}
]},
{"state": "> Esi wrote: Absolutely furious. Nobody answers.", "questions": [
{"type": "multiclass", "instruction": "A request type is the specific thing the sender asks staff to do. Which request type does this quoted reply contain?", "candidates": [{"id": "refund", "description": "Asks for money back, e.g. 'return my fee'"}, {"id": "grade_review", "description": "Asks for a mark to be rechecked, e.g. 'please re-grade my essay'"}, {"id": "none", "description": "None of the above: no specific request, e.g. only venting 'this is awful'"}], "target": "none", "hard_cases": [], "notes": "only complaint about no replies; no specific ask"},
{"type": "binary", "instruction": "A responsiveness complaint means the sender objects that staff are not replying. Is there one here?", "target": true, "hard_cases": [], "notes": "'Nobody answers'"}
]}]

[{"state": "HOST Nadia Haddad: so the museum cancelled your Saturday tour on you? GUEST Dalia Novak: nope, I cancelled on them, they were lovely, I just booked the wrong weekend, classic me honestly.", "questions": [
{"type": "binary", "instruction": "did the museum cancel on her?", "target": false, "hard_cases": ["role_reversal"], "notes": "Dalia says she cancelled on the museum, not the reverse"},
{"type": "binary", "instruction": "so the guest cancelled herself, right?", "target": true, "hard_cases": ["role_reversal"], "notes": "'I cancelled on them', said by the guest Dalia"},
