{"type": "multiclass", "instruction": "who filed the main claim?", "candidates": [{"id": "kestrel", "description": "kestrel_software"}, {"id": "harbor", "description": "harbor_studio"}, {"id": "none", "description": "none_of_above"}], "target": "harbor", "hard_cases": ["role_reversal"], "notes": "Harbor Studio is the plaintiff; Kestrel only counterclaims"}
